@RelationalLimit.free_omega_lift_lub
     : forall (MN : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (NO : @Omega.SemanticOmega MN NI) (A B : Type) (RR : A -> B -> Prop)
         (left : nat -> Definition.FreeOmega MN A) (right : nat -> Definition.FreeOmega MN B)
         (out1 : Definition.FreeOmega MN A) (out2 : Definition.FreeOmega MN B),
       @Omega.sem_lub (Definition.FreeOmega MN)
         (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO)
         (@Measure.FreeOmegaObservableSemanticOmega MN NI NO) A left out1 ->
       @Omega.sem_lub (Definition.FreeOmega MN)
         (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO)
         (@Measure.FreeOmegaObservableSemanticOmega MN NI NO) B right out2 ->
       (forall n : nat,
        @Measure.sem_lift (Definition.FreeOmega MN)
          (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO) A B RR
          (left n) (right n)) ->
       @Measure.sem_lift (Definition.FreeOmega MN)
         (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO) A B RR out1 out2

@Scheduling.ptree_interp_hitting_le_diagonal
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X)
         (A : Type) (n : nat) (t : PTreeDefinition.ptree E MN A),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head F MN A)
         (@PTreeKernel.ptree_hitting_approx F MN MF FI MX FO A n
            (@PTreeDefinition.observe F MN A (@PTreeDefinition.PTree.interp E F MN handler A t)))
         (@Scheduling.ptree_interp_split_approx E F MN MF FI MX FO handler A n n t)

